ON DUPLICATE KEY 
UPDATE 
    -- if the existing value and new value DO NOT equal eachother
        -- return the "new" inserted values "value"
        -- else current column "value"
    `name` = IF(`name` <> VALUES(`name`), VALUES(`name`), `name`),
    `packet_name` = IF(`packet_name` <> VALUES(`packet_name`), VALUES(`packet_name`), `packet_name`),
    `familyid` = IF(`familyid` <> VALUES(`familyid`), VALUES(`familyid`), `familyid`),
    `modelid` = IF(`modelid` <> VALUES(`modelid`), VALUES(`modelid`), `modelid`),
    `mJob` = IF(`mJob` <> VALUES(`mJob`), VALUES(`mJob`), `mJob`),
    `sJob` = IF(`sJob` <> VALUES(`sJob`), VALUES(`sJob`), `sJob`),
