ON DUPLICATE KEY 
UPDATE 
    -- if the existing value and new value DO NOT equal eachother
        -- return the "new" inserted values "value"
        -- else current column "value"
    `name` = IF(`name` <> VALUES(`name`), VALUES(`name`), `name`),
    `packet_name` = IF(`packet_name` <> VALUES(`packet_name`), VALUES(`packet_name`), `packet_name`),
    `familyid` = IF(`familyid` <> VALUES(`familyid`), VALUES(`familyid`), `familyid`),
    `modelid` = IF(`modelid` <> VALUES(`modelid`), VALUES(`modelid`), `modelid`),
    `mJob` = IF(`mJob` <> VALUES(`mJob`), VALUES(`mJob`), `mJob`),
    `sJob` = IF(`sJob` <> VALUES(`sJob`), VALUES(`sJob`), `sJob`),
    `cmbSkill` = IF(`cmbSkill` <> VALUES(`cmbSkill`), VALUES(`cmbSkill`), `cmbSkill`),
    `cmbDelay` = IF(`cmbDelay` <> VALUES(`cmbDelay`), VALUES(`cmbDelay`), `cmbDelay`),
    `cmbDmgMult` = IF(`cmbDmgMult` <> VALUES(`cmbDmgMult`), VALUES(`cmbDmgMult`), `cmbDmgMult`),
    `behavior` = IF(`behavior` <> VALUES(`behavior`), VALUES(`behavior`), `behavior`),
    `aggro` = IF(`aggro` <> VALUES(`aggro`), VALUES(`aggro`), `aggro`),
    `true_detection` = IF(`true_detection` <> VALUES(`true_detection`), VALUES(`true_detection`), `true_detection`),
    `links` = IF(`links` <> VALUES(`links`), VALUES(`links`), `links`),
    `mobType` = IF(`mobType` <> VALUES(`mobType`), VALUES(`mobType`), `mobType`),
    `immunity` = IF(`immunity` <> VALUES(`immunity`), VALUES(`immunity`), `immunity`),
    `name_prefix` = IF(`name_prefix` <> VALUES(`name_prefix`), VALUES(`name_prefix`), `name_prefix`),
    `flag` = IF(`flag` <> VALUES(`flag`), VALUES(`flag`), `flag`),
    `entityFlags` = IF(`entityFlags` <> VALUES(`entityFlags`), VALUES(`entityFlags`), `entityFlags`),
    `animationsub` = IF(`animationsub` <> VALUES(`animationsub`), VALUES(`animationsub`), `animationsub`),
    `hasSpellScript` = IF(`hasSpellScript` <> VALUES(`hasSpellScript`), VALUES(`hasSpellScript`), `hasSpellScript`),
    `spellList` = IF(`spellList` <> VALUES(`spellList`), VALUES(`spellList`), `spellList`),
    `namevis` = IF(`namevis` <> VALUES(`namevis`), VALUES(`namevis`), `namevis`),
    `roamflag` = IF(`roamflag` <> VALUES(`roamflag`), VALUES(`roamflag`), `roamflag`),
    `skill_list_id` = IF(`skill_list_id` <> VALUES(`skill_list_id`), VALUES(`skill_list_id`), `skill_list_id`),
    `resist_id` = IF(`resist_id` <> VALUES(`resist_id`), VALUES(`resist_id`), `resist_id`),
    `modelSize` = IF(`modelSize` <> VALUES(`modelSize`), VALUES(`modelSize`), `modelSize`),
    `modelHitboxSize` = IF(`modelHitboxSize` <> VALUES(`modelHitboxSize`), VALUES(`modelHitboxSize`), `modelHitboxSize`)
;

insert into `mob_pools`
(
    `poolid`, `name`, `packet_name`, `familyid`, `modelid`, `mJob`, `sJob`, `cmbSkill`, `cmbDelay`,
    `cmbDmgMult`, `behavior`, `aggro`, `true_detection`, `links`, `mobType`, `immunity`,
    `name_prefix`, `flag`, `entityFlags`, `animationsub`, `hasSpellScript`, `spellList`,
    `namevis`, `roamflag`, `skill_list_id`, `resist_id`, `modelSize`, `modelHitboxSize`
)
